import type { Caption } from "@remotion/captions";

// Edit timelines generated by student-interviews/edit/build.py.

export type StudentInfo = {
  // Approximate face centre in the 1080×1920 proxy.
  face: number[];
  file: string;
  name: string;
  age: string;
  from: string;
  uni: string;
  program: string;
  city: string;
  // "Бакалавриат" or "Магистратура".
  level: string;
  female: boolean;
  // Paths inside the media folder.
  avatar: string;
  photo: string | null;
};

export type MarcoPose = "point" | "present" | "notebook" | "peace" | "open";

export type Prop = {
  kind: string;
  label: string;
  // Seconds on the output timeline: the cue word's start and its answer's end.
  at: number;
  until: number;
  slot: number;
};

export type Segment = {
  src: string;
  // Source range in seconds.
  from: number;
  to: number;
  // Position on the output timeline in seconds.
  at: number;
  student: string;
  item: number;
  cut: "start" | "jump" | "switch";
  // Source time before which the audio stays muted (a held question beat).
  muteUntil?: number;
};

export type Item =
  | {
      kind: "clip";
      student: string;
      start: number;
      end: number;
      hook?: boolean;
      passport?: boolean;
      bubble?: string;
      bubbleLead?: number;
      truth?: string;
    }
  | {
      kind: "title" | "myth" | "chapter" | "end";
      text: string;
      // Pose of Marco, the mascot, shown on the card.
      marco?: MarcoPose;
      start: number;
      end: number;
    };

export type VoicesData = {
  id: string;
  format: "story" | "question" | "reviews" | "myths" | "paper";
  title: string;
  // Overrides the title card's kicker for the format.
  kicker?: string | null;
  question: string | null;
  // Paper edit only: the music bed and the props that pop in on cue words.
  music?: string | null;
  props?: Prop[];
  durationSec: number;
  durationInFrames: number;
  students: Record<string, StudentInfo>;
  order: string[];
  segments: Segment[];
  items: Item[];
  captions: (Caption & { pageBreakAfter?: boolean })[];
};
